import java.util.*;
import java.io.*;

public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String patternInput = br.readLine();
        int limit = 1;
        for (int i = 0; i < patternInput.length(); i++) {
            limit *= 10;
        }
        int matchCount = 0;
        for (int number = 0; number < limit; number += 25) {
            if (patternMatches(patternInput, number)) {
                matchCount++;
            }
        }
        pw.println(matchCount);
        pw.close();
    }

    public static boolean patternMatches(String pattern, int num) {
        int lastDigit = -1;
        for (int i = pattern.length() - 1; i >= 0; i--) {
            int currentDigit = num % 10;
            char c = pattern.charAt(i);
            if (c == 'X') {
                if (lastDigit >= 0 && lastDigit != currentDigit) {
                    return false;
                }
                lastDigit = currentDigit;
            } else if (c != '_') {
                if (c - '0' != currentDigit) {
                    return false;
                }
            }
            if (pattern.length() > 1 && i == 0 && currentDigit == 0) {
                return false;
            }
            num /= 10;
        }
        return true;
    }
}
