#include <bits/stdc++.h>
using namespace std;

bool patternMatches(const string& pattern, int num) {
    int lastDigit = -1;
    int n = pattern.length();
    for (int i = n - 1; i >= 0; i--) {
        int currentDigit = num % 10;
        char c = pattern[i];
        if (c == 'X') {
            if (lastDigit >= 0 && lastDigit != currentDigit) {
                return false;
            }
            lastDigit = currentDigit;
        } else if (c != '_') {
            if ((c - '0') != currentDigit) {
                return false;
            }
        }
        if (n > 1 && i == 0 && currentDigit == 0) {
            return false;
        }
        num /= 10;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string patternInput;
    getline(cin, patternInput);
    int limit = 1;
    for (size_t i = 0; i < patternInput.length(); i++) {
        limit *= 10;
    }
    int matchCount = 0;
    for (int number = 0; number < limit; number += 25) {
        if (patternMatches(patternInput, number)) {
            matchCount++;
        }
    }
    cout << matchCount << "\n";
    return 0;
}

